--- Open a Chrome tab in a new window with the same size as the current one

fileInfo()

local conditions = hs.hotkey.conditions

hs.hotkey
    .when(conditions.inApps("Google Chrome"))
    .bind(
        hyper,
        "t",
        keyInfo("Open Tab in new Window"),
        function()
            local menuItemNames = { "Tab in ein neues Fenster verschieben", "Move Tab to New Window" }
            local options = { alertPrefix = "Move Tab" }
            applicationSelectMenuItemApplySameFrame(menuItemNames, options)
        end
    )
